import type { QuizChoice, QuizQuestion } from './types';

type Seed = [text: string, reason: string];
const js = 'https://developer.mozilla.org/en-US/docs/Web/JavaScript/';
const web = 'https://developer.mozilla.org/en-US/docs/Web/API/';
const nist = 'https://xlinux.nist.gov/dads/HTML/';

function make(
  number: number, level: QuizQuestion['level'], kind: QuizQuestion['kind'], topic: string,
  prompt: string, seeds: [Seed, Seed, Seed, Seed], explanation: string,
  relatedTermIds: string[], source: string, code?: string, expectedLogs?: string[],
): QuizQuestion {
  const choiceIds = ['a', 'b', 'c', 'd'] as const;
  const correctIndex = (number - 1) % 4;
  const ordered = seeds.slice(1);
  ordered.splice(correctIndex, 0, seeds[0]);
  const choices = ordered.map(([text, reason], index) => ({ id: choiceIds[index], text, explanation: reason })) as [QuizChoice, QuizChoice, QuizChoice, QuizChoice];
  return { id: `js-extra-${level}-${String(number).padStart(2, '0')}`, part: 'javascript', level, kind, topic,
    prompt, choices, correctChoiceId: choiceIds[correctIndex], explanation, relatedTermIds, source,
    ...(code ? { code, codeLanguage: 'javascript' as const } : {}), ...(expectedLogs ? { expectedLogs } : {}) };
}

